  INSERT INTO journal_entries (user_id, journal_date, compliance, emotional_state, discipline_rating, reflection, key_lesson, demo) VALUES
      (p_user_id, '2026-08-03'::date, 5, 'CALM', 9, '[DEMO DATA] Followed the pre-market routine. Waited for acceptance back into value before entering gold.', 'Patience at value edges pays.', true),
      (p_user_id, '2026-08-06'::date, 3, 'ANXIOUS', 5, '[DEMO DATA] Entered NAS short late after missing the initial move. Location was poor.', 'If I missed it, I missed it.', true),
      (p_user_id, '2026-08-11'::date, 1, 'REVENGE', 2, '[DEMO DATA] Three oil losses in under 30 minutes. Chased the headline, flipped in revenge, then moved my stop. Classic tilt.', 'After two losses in a session, stop trading for the day.', true),
      (p_user_id, '2026-08-14'::date, 5, 'FOCUSED', 9, '[DEMO DATA] Reset after the tilt day. Took only A+ volume-profile setups.', 'Fewer trades, better trades.', true),
      (p_user_id, '2026-08-24'::date, 2, 'GREEDY', 4, '[DEMO DATA] Doubled position size after two winners. The loss cost more than both wins combined.', 'Size is fixed by the plan, not by mood.', true),
      (p_user_id, '2026-08-28'::date, 3, 'ANXIOUS', 6, '[DEMO DATA] Closed gold short at 0.6R on noise. Price hit my target an hour later.', 'Let the stop and target do their job.', true),
      (p_user_id, '2026-09-02'::date, 5, 'CALM', 10, '[DEMO DATA] Best execution of the month on the VAL bounce.', 'My edge is strongest at London open on gold.', true),
      (p_user_id, '2026-09-04'::date, 2, 'FOMO', 3, '[DEMO DATA] Traded into NFP despite my rule. Pure gamble.', 'No positions 15 minutes either side of tier-1 news.', true),
      (p_user_id, '2026-09-11'::date, 1, 'FRUSTRATED', 2, '[DEMO DATA] Did not place a hard stop on NAS. Mental stop failed and the loss reached 2R.', 'Hard stop is placed before the entry fills. Always.', true),
      (p_user_id, '2026-09-17'::date, 2, 'BORED', 4, '[DEMO DATA] Off-hours BTC trade out of boredom.', 'Close the platform when the session ends.', true),
      (p_user_id, '2026-09-24'::date, 5, 'FOCUSED', 9, '[DEMO DATA] Oil VAH rejection executed exactly to plan.', 'Checklist before every entry.', true),
      (p_user_id, '2026-10-02'::date, 3, 'ANXIOUS', 6, '[DEMO DATA] Took a B-setup on EURUSD outside my plan, then recovered with a clean NAS silver bullet.', 'Only trade the playbook.', true),
      (p_user_id, '2026-10-05'::date, 5, 'CALM', 9, '[DEMO DATA] Strong start to October. Two winners, one valid loss.', 'Valid losses are part of the edge.', true)
